Deque<Integer> deque = new LinkedList<>();
for (int i = 0; i < N; i++) {
  // Remove smaller elements from back (for max)
  while (!deque.isEmpty() && A[i] >= A[deque.peekLast()]) {
    deque.removeLast();
  }
  deque.offerLast(i);

  // Remove front if out of window
  while (deque.peekFirst() < i - K + 1) {
    deque.removeFirst();
  }

  // Window fully formed?
  if (i >= K - 1) {
    result[i-K+1] = A[deque.peekFirst()];
  }
}

Stack<Integer> inputStack = new Stack<>();
Stack<Integer> outputStack = new Stack<>();

void push(int X) {
  inputStack.push(X);
}

int pop() {
  transferIfNeeded();
  return outputStack.pop();
}

int peek() {
  transferIfNeeded();
  return outputStack.peek();
}

void transferIfNeeded() {
  if (outputStack.isEmpty()) {
    while (!inputStack.isEmpty()) {
      outputStack.push(inputStack.pop());
    }
  }
}

