HashMap<Character, Integer> map = new HashMap<>();
Deque<Character> deque = new LinkedList<>();
StringBuilder result = new StringBuilder();

for (char x : stream.toCharArray()) {
  // Update frequency
  map.put(x, map.getOrDefault(x, 0) + 1);

  // Add to deque on first occurrence
  if (map.get(x) == 1) {
    deque.offerLast(x);
  }

  // Clean front: remove repeated characters
  while (!deque.isEmpty() && map.get(deque.peekFirst()) > 1) {
    deque.removeFirst();
  }

  // Answer: front of deque or default
  result.append(deque.isEmpty() ? '#' : deque.peekFirst());
}

